import json
from collections import Counter

with open("/tmp/all_notes.json", "r") as f:
    notes = json.load(f)

print(f"Total notes: {len(notes)}\n")

# 1. Note type distribution
note_types = Counter(n.get("note_type", "unknown") for n in notes)
print("=" * 55)
print("1. 笔记类型分布 (note_type)")
print("=" * 55)
for t, c in note_types.most_common():
    print(f"  {t:30s}  {c:4d}  ({c*100/len(notes):.1f}%)")

# 2. Source distribution
sources = Counter(n.get("source", "unknown") for n in notes)
print("\n" + "=" * 55)
print("2. 来源分布 (source)")
print("=" * 55)
for s, c in sources.most_common():
    print(f"  {s:30s}  {c:4d}  ({c*100/len(notes):.1f}%)")

# 3. Tags distribution
all_tags = []
for n in notes:
    tags = n.get("tags", [])
    if tags:
        for tag in tags:
            if isinstance(tag, str):
                all_tags.append(tag)
            elif isinstance(tag, dict):
                all_tags.append(tag.get("name", str(tag)))
tag_counts = Counter(all_tags)
print("\n" + "=" * 55)
print("3. 标签分布 (tags) - Top 20")
print("=" * 55)
if tag_counts:
    for t, c in tag_counts.most_common(20):
        print(f"  {t:30s}  {c:4d}")
else:
    print("  (无标签)")

# 4. Topics distribution
all_topics = []
for n in notes:
    topics = n.get("topics", [])
    if topics:
        for t in topics:
            if isinstance(t, dict):
                all_topics.append(t.get("name", "?"))
            elif isinstance(t, str):
                all_topics.append(t)
topic_counts = Counter(all_topics)
print("\n" + "=" * 55)
print("4. 话题分布 (topics) - Top 20")
print("=" * 55)
if topic_counts:
    for t, c in topic_counts.most_common(20):
        print(f"  {t:30s}  {c:4d}  ({c*100/len(notes):.1f}%)")
else:
    print("  (无话题)")

# 5. Title word/semantic analysis - content themes
print("\n" + "=" * 55)
print("5. 标题关键词词频 (Top 30)")
print("=" * 55)
title_words = []
import re
stopwords = set(['的', '了', '和', '与', '是', '在', '我', '你', '他', '她', '它', '们', '这', '那', '有', '为', '与', '及', '等', '或', '也', '都', '被', '将', '把', '从', '到', '对', '以', '及', '中', '上', '下', '不', '会', '可', '能', '要', '去', '来', '过', '出', '进', '一', '个', '之', '于', '年', '月', '日', '时', '分', '秒', '第', '其', '而', '则', '但', '因', '所', '让', '给', '做', '成', '为', '如', '当', '此', '种', '并', '更', '只', '还', '又', '很', '最', '再', '已', '应', '该', '没', '很', '多', '少', '两', '各', '每', '某', '比', '向', '通过', '关于', '如何', '什么', '为什么'])
for n in notes:
    title = n.get("title", "")
    # Extract Chinese words (2-char+)
    words = re.findall(r'[\u4e00-\u9fa5]{2,}', title)
    for w in words:
        if w not in stopwords and len(w) >= 2:
            title_words.append(w)
word_counts = Counter(title_words)
for w, c in word_counts.most_common(30):
    print(f"  {w:20s}  {c:4d}")

# 6. Sample titles by type
print("\n" + "=" * 55)
print("6. 各类型笔记标题样例")
print("=" * 55)
type_examples = {}
for n in notes:
    nt = n.get("note_type", "?")
    if nt not in type_examples:
        type_examples[nt] = []
    if len(type_examples[nt]) < 3:
        title = n.get("title", "(无标题)")
        type_examples[nt].append(title)

for nt, titles in sorted(type_examples.items()):
    print(f"\n[{nt}] ({note_types[nt]}条)")
    for t in titles[:3]:
        print(f"  • {t[:70]}")

EOF
